#include <bits/stdc++.h>
using namespace std;

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    struct PieceData {
        int k;
        vector<pair<int,int>> cells;
    };
    vector<PieceData> pieces(n);
    int totalCells = 0;
    for(int i = 0; i < n; i++){
        cin >> pieces[i].k;
        pieces[i].cells.resize(pieces[i].k);
        for(int j = 0; j < pieces[i].k; j++){
            cin >> pieces[i].cells[j].first >> pieces[i].cells[j].second;
        }
        totalCells += pieces[i].k;
    }

    // Precompute orientations for each piece
    struct OriInfo {
        vector<pair<int,int>> cells; // normalized, sorted
        int w, h;
        int f, r;
    };

    vector<vector<OriInfo>> allOris(n);
    for(int i = 0; i < n; i++){
        set<vector<pair<int,int>>> seen;
        for(int f = 0; f < 2; f++){
            for(int r = 0; r < 4; r++){
                vector<pair<int,int>> tc;
                for(auto [x, y] : pieces[i].cells){
                    int nx = x, ny = y;
                    if(f) nx = -nx;
                    for(int q = 0; q < r; q++){
                        int tmp = nx;
                        nx = ny;
                        ny = -tmp;
                    }
                    tc.push_back({nx, ny});
                }
                int minx = INT_MAX, miny = INT_MAX;
                for(auto [x,y] : tc){ minx = min(minx,x); miny = min(miny,y); }
                for(auto& [x,y] : tc){ x -= minx; y -= miny; }
                sort(tc.begin(), tc.end());
                if(seen.insert(tc).second){
                    int w = 0, h = 0;
                    for(auto [x,y] : tc){ w = max(w,x+1); h = max(h,y+1); }
                    allOris[i].push_back({tc, w, h, f, r});
                }
            }
        }
    }

    // Sort pieces: largest first, break ties by fewer orientations (harder to place)
    vector<int> order(n);
    iota(order.begin(), order.end(), 0);
    sort(order.begin(), order.end(), [&](int a, int b){
        if(pieces[a].k != pieces[b].k) return pieces[a].k > pieces[b].k;
        return allOris[a].size() < allOris[b].size();
    });

    auto startTime = chrono::steady_clock::now();
    auto elapsed = [&]() -> double {
        return chrono::duration<double>(chrono::steady_clock::now() - startTime).count();
    };

    int bestArea = INT_MAX;
    int bestH = INT_MAX, bestW = INT_MAX;
    struct Placement { int x,y,r,f; };
    vector<Placement> bestPlacements(n);

    // Try several widths
    double sqrtArea = sqrt((double)totalCells * 1.05);
    vector<int> candidateWidths;
    for(double mult = 0.7; mult <= 2.5; mult += 0.15){
        int w = max(10, (int)round(sqrtArea * mult));
        candidateWidths.push_back(w);
    }
    sort(candidateWidths.begin(), candidateWidths.end());
    candidateWidths.erase(unique(candidateWidths.begin(), candidateWidths.end()), candidateWidths.end());

    for(int W : candidateWidths){
        if(elapsed() > 8.0 && bestArea < INT_MAX) break;
        if(elapsed() > 9.0) break;

        int maxH = (totalCells + W - 1) / W + 20;
        // Use heightmap per column
        vector<int> hmap(W, 0);
        // Grid for occupancy
        vector<vector<bool>> grid(W, vector<bool>(maxH, false));

        vector<Placement> placements(n);
        int curMaxY = 0;
        bool failed = false;

        for(int idx = 0; idx < n; idx++){
            if(elapsed() > 9.5){ failed = true; break; }
            int pi = order[idx];

            int bestScore = INT_MAX;
            int bx = -1, by = -1, boi = -1;

            for(int oi = 0; oi < (int)allOris[pi].size(); oi++){
                auto& ori = allOris[pi][oi];
                if(ori.w > W) continue;

                for(int x = 0; x <= W - ori.w; x++){
                    // Find min y using heightmap
                    int minY = 0;
                    for(auto& [cx, cy] : ori.cells){
                        minY = max(minY, hmap[x+cx] - cy);
                    }
                    if(minY < 0) minY = 0;

                    // Check bounds
                    int topY = 0;
                    for(auto& [cx,cy] : ori.cells) topY = max(topY, minY+cy+1);
                    if(topY > maxH){ continue; }

                    // Check overlap
                    bool ok = true;
                    for(auto& [cx,cy] : ori.cells){
                        if(grid[x+cx][minY+cy]){ ok = false; break; }
                    }

                    if(ok){
                        int score = topY * 10000 + x;
                        if(score < bestScore){
                            bestScore = score;
                            bx = x; by = minY; boi = oi;
                        }
                    }
                }
            }

            if(bx == -1){ failed = true; break; }

            auto& ori = allOris[pi][boi];
            for(auto& [cx,cy] : ori.cells){
                grid[bx+cx][by+cy] = true;
                hmap[bx+cx] = max(hmap[bx+cx], by+cy+1);
                curMaxY = max(curMaxY, by+cy+1);
            }
            placements[pi] = {bx, by, ori.r, ori.f};
        }

        if(failed) continue;

        int H = curMaxY;
        long long area = (long long)W * H;
        if(area < bestArea || (area == bestArea && (H < bestH || (H == bestH && W < bestW)))){
            bestArea = area;
            bestH = H;
            bestW = W;
            bestPlacements = placements;
        }
    }

    // Fallback: if nothing worked, place in a single very wide row
    if(bestArea == INT_MAX){
        int W = totalCells + 10*n;
        int cx = 0;
        for(int i = 0; i < n; i++){
            auto& ori = allOris[i][0];
            bestPlacements[i] = {cx, 0, ori.r, ori.f};
            cx += ori.w;
        }
        bestW = cx;
        bestH = 11;
    }

    cout << bestW << " " << bestH << "\n";
    for(int i = 0; i < n; i++){
        cout << bestPlacements[i].x << " " << bestPlacements[i].y << " "
             << bestPlacements[i].r << " " << bestPlacements[i].f << "\n";
    }

    return 0;
}
